			std::string directory = ContentProvider::singleton().assetFolder() + "Sky\\";
			G3D::SkyRef g3dSky = G3D::Sky::fromFile(NULL, directory, filenames, sky->drawCelestialBodies, 1.0);

			if (g3dSky.notNull()) {
